contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        uint256 reserveBefore = address(c).balance;
        uint256 balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 reserveAfter = address(c).balance;
        uint256 balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(!reverted ? (reserveAfter <= reserveBefore && balAfter <= balBefore) : true);
    }

    receive() external payable {}
}

